css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader span { position: absolute; inset: 0; border-radius: 50%; background: repeating-radial-gradient(circle, #191919 0 2px, #2b2b2b 2px 4px); box-shadow: inset 0 0 calc(var(--loader-size) * .12) rgba(0, 0, 0, .7); animation: spin calc(var(--loader-speed) * 2) linear infinite; }
.loader span::after { content: ''; position: absolute; inset: 34%; border-radius: 50%; background: radial-gradient(circle, #111 0 12%, var(--accent) 13% 100%); border: 2px solid var(--accent-2); box-sizing: border-box; }
.loader::before { content: ''; position: absolute; z-index: 2; top: 2%; right: 12%; width: calc(var(--loader-size) * .045); height: 54%; background: #94a3b8; border-radius: 4px; transform-origin: top center; transform: rotate(24deg); }
@keyframes spin { to { transform: rotate(360deg); } }
